/// <summary>
/// runService
/// </summary>
/// <param name = "_dataContract">AVADAIReportAcknowledgmentImportProtocolCleanUpDataContract</param>
public void runService(AVADAIReportAcknowledgmentImportProtocolCleanUpDataContract _dataContract)
{
    QueryRun                        queryRun;
    AVADAIAcknowledgementImport     reportImportTable;

    // create a new queryrun object
    query query = _dataContract.getQuery();
    query.dataSourceTable(tableNum(AVADAIAcknowledgementImport)).update(true);
    queryRun    = new queryRun(query);

    // loop all results from the query
    ttsbegin;
    while(queryRun.next())
    {
        reportImportTable = queryRun.get(tableNum(AVADAIAcknowledgementImport));
        reportImportTable.delete();
    }
    ttscommit;
}
